{
  "name": "ipyparaview",
  "version": "0.1.2",
  "description": "A widget for interactive server-side ParaView rendering",
  "author": "Nick Leaf",
  "main": "lib/index.js",
  "repository": {
    "type": "git",
    "url": "https://github.com/NVIDIA/ipyparaview.git"
  },
  "keywords": [
    "jupyter",
    "widgets",
    "ipython",
    "ipywidgets",
    "jupyterlab-extension"
  ],
  "files": [
    "lib/**/*.js",
    "dist/*.js"
  ],
  "scripts": {
    "clean": "rimraf dist/",
    "prepublish": "webpack",
    "build": "webpack",
    "watch": "webpack --watch --mode=development",
    "test": "echo \"Error: no test specified\" && exit 1"
  },
  "devDependencies": {
    "webpack": "^3.5.5",
    "rimraf": "^2.6.1"
  },
  "dependencies": {
    "@jupyter-widgets/base": "^1.1 || ^2 || ^3",
    "lodash": "^4.17.4"
  },
  "jupyterlab": {
    "extension": "lib/labplugin"
  }
}

{
  "load_extensions": {
    "ipyparaview/extension": true
  }
}

#!/bin/bash

cd "$( cd "$( dirname "${BASH_SOURCE[0]}" )" >/dev/null 2>&1 && pwd )"/../notebooks

jupyter notebook

{
  "family" : "OSPRay",
  "version" : "0.0",
  "materials" : {
    "Green Paint": {
      "type": "CarPaint",
      "doubles" : {
          "baseColor" : [0.115, 1.0, 0.0],
          "coatColor" : [0.292, 0.824, 0.076],
          "flakeDensity" : [0.7],
          "flakeRoughness" : [0.3],
          "flakeScale" : [10000.0],
          "flakeSpread" : [0.35]
      }
    },
    "Logo": {
      "type": "Principled",
      "doubles" : {
        "coatColor" : [1.0, 1.0, 1.0],
        "coat" : [0.6],
        "metallic" : [1.0],
        "roughness" : [0.2]
      },
      "textures" : {
        "baseColorMap" : "/notebooks/NVIDIA_Logo.jpg"
      }      
    },
    "Glass": {
      "type": "ThinGlass",
      "doubles" : {
          "attenuationColor" : [0.85, 0.9, 1.0]
      }
    },
    "Chromium": {
      "type": "Metal",
      "doubles" : {
          "eta" : [3.2, 3.1, 2.3],
          "k" : [3.3, 3.3, 3.1],
          "roughness" : [0.2]
      }
    },

    "Red Glass": {
      "type": "ThinGlass",
      "doubles" : {
          "attenuationColor" : [1.0, 0.0, 0.0]
      }
    },

    "Black Paint": {
      "type": "CarPaint",
      "doubles" : {
          "baseColor" : [0.11, 0.097, 0.0097],
          "coatColor" : [0.053, 0.055, 0.052],
          "flakeDensity" : [0.5],
          "flakeRoughness" : [0.3],
          "flakeScale" : [10000.0],
          "flakeSpread" : [0.3]
      }
    },

    "Metal": {
      "type": "Metal",
      "doubles" : {
          "eta" : [1.5, 0.98, 0.6],
          "k" : [7.6, 6.6, 5.4],
          "roughness" : [0.2]
      }
    },

    "Gold": {
      "type": "Metal",
      "doubles" : {
          "eta" : [0.07, 0.37, 1.5],
          "k" : [3.7, 2.3, 1.7],
          "roughness" : [0.2]
      }
    },

    "Rubber": {
      "type": "Principled",
      "doubles" : {
          "baseColor" : [0.15, 0.15, 0.15],
          "metallic" : [0.8],
          "roughness" : [0.6]
      }
    },

    "Amber": {
      "type": "Glass",
      "doubles" : {
          "attenuationColor" : [1.0, 0.91, 0.084],
          "attenuationDistance" : [0.7],
          "eta" : [1.55]
      }
    },

    "Water": {
      "type": "Glass",
      "doubles" : {
          "attenuationColor" : [0.0, 0.559, 1.0],
          "attenuationDistance" : [1.0],
          "eta" : [1.33]
      }
    },

    "Diamond": {
      "type": "Glass",
      "doubles" : {
          "attenuationColor" : [0.96, 0.96, 1.0],
          "attenuationDistance" : [1.0],
          "eta" : [1.5]
      }
    },

    "Air": {
      "type": "Glass",
      "doubles" : {
          "attenuationColor" : [1.0, 1.0, 1.0],
          "attenuationDistance" : [1.0],
          "eta" : [1.0]
      }
    }

  }
}

var path = require('path');
var version = require('./package.json').version;

// Custom webpack rules are generally the same for all webpack bundles, hence
// stored in a separate local variable.
var rules = [
    { test: /\.css$/, use: ['style-loader', 'css-loader']}
]


module.exports = [
    {// Notebook extension
     //
     // This bundle only contains the part of the JavaScript that is run on
     // load of the notebook. This section generally only performs
     // some configuration for requirejs, and provides the legacy
     // "load_ipython_extension" function which is required for any notebook
     // extension.
     //
        entry: './lib/extension.js',
        output: {
            filename: 'extension.js',
            path: path.resolve(__dirname, '..', 'ipyparaview', 'static'),
            libraryTarget: 'amd'
        }
    },
    {// Bundle for the notebook containing the custom widget views and models
     //
     // This bundle contains the implementation for the custom widget views and
     // custom widget.
     // It must be an amd module
     //
        entry: './lib/index.js',
        output: {
            filename: 'index.js',
            path: path.resolve(__dirname, '..', 'ipyparaview', 'static'),
            libraryTarget: 'amd'
        },
        devtool: 'source-map',
        module: {
            rules: rules
        },
        externals: ['@jupyter-widgets/base']
    },
    {// Embeddable ipyparaview bundle
     //
     // This bundle is generally almost identical to the notebook bundle
     // containing the custom widget views and models.
     //
     // The only difference is in the configuration of the webpack public path
     // for the static assets.
     //
     // It will be automatically distributed by unpkg to work with the static
     // widget embedder.
     //
     // The target bundle is always `dist/index.js`, which is the path required
     // by the custom widget embedder.
     //
        entry: './lib/embed.js',
        output: {
            filename: 'index.js',
            path: path.resolve(__dirname, 'dist'),
            libraryTarget: 'amd',
            publicPath: 'https://unpkg.com/ipyparaview@' + version + '/dist/'
        },
        devtool: 'source-map',
        module: {
            rules: rules
        },
        externals: ['@jupyter-widgets/base']
    }
];

// Export widget models and views, and the npm package version number.
module.exports = require('./widgets.js');
module.exports['version'] = require('../package.json').version;
